file.content:
  gap: 10px;
  max-width: 100%;
  position: relative;
}
.msg.user  { flex-direction: row-reverse; }
.msg.user  .bubble { background: var(--user-bg); border: 1px solid var(--green); margin-left: 40px; }
.msg.bot   .bubble { background: var(--surface); border: 1px solid var(--border); margin-right: 40px; position: relative; }

/* Copy button for bot messages */
.msg.bot .copy-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 11px;
  cursor: pointer;
  color: var(--muted);
  opacity: 0;
  transition: opacity .15s, color .15s, border-color .15s;
}
.msg.bot:hover .copy-btn { opacity: 1; }
.msg.bot .copy-btn:hover { color: var(--green); border-color: var(--green); }
.msg.bot .copy-btn.copied { color: var(--green); opacity: 1; }

.avatar {
  width: 30px; height: 30px; border-radius: 50%;
  flex-shrink: 0; display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  overflow: hidden;
}
.msg.user .avatar { background: var(--green); color: #fff; }
.msg.bot  .avatar { background: var(--surface); border: 1px solid var(--border); }
.msg.bot  .avatar img { width: 100%; height: 100%; object-fit: contain; }

.bubble {
  padding: 10px 14px;
  border-radius: 12px;
  white-space: pre-wrap;
  word-break: break-word;
  line-height: 1.55;
}
.msg-timestamp {
  font-size: 11px;
  color: var(--muted, #999);
  margin-top: 2px;
  padding: 0 4px;
}
.msg.user .msg-timestamp { text-align: right; }
.bubble strong { font-weight: 600; }
.bubble em { font-style: italic; }
.bubble code {
  background: rgba(255, 255, 255, 0.1);
  padding: 2px 6px;
  border-radius: 4px;
  font-family: 'SF Mono', Monaco, 'Cascadia Code', monospace;
  font-size: 13px;
}
.bubble a {
  color: var(--blue);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color .15s;
}
.bubble a:hover { border-bottom-color: var(--blue); }

/* Markdown headers */
.bubble h1 { font-size: 20px; font-weight: 700; margin: 16px 0 10px; color: var(--text); }
.bubble h2 { font-size: 18px; font-weight: 600; margin: 14px 0 8px; color: var(--text); }
.bubble h3 { font-size: 16px; font-weight: 600; margin: 12px 0 6px; color: var(--text); }
.bubble h1 + br, .bubble h2 + br, .bubble h3 + br { display: none; } /* Remove line breaks after headers */

/* Markdown tables */
.bubble table {
  width: 100%;
  border-collapse: collapse;
  margin: 12px 0;
  background: rgba(255, 255, 255, 0.03);
  border-radius: 6px;
  overflow: hidden;
}
.bubble table td {
  padding: 8px 12px;
  border: 1px solid var(--border);
  line-height: 1.4;
  word-wrap: break-word;
  word-break: break-word;
  hyphens: auto;
  -webkit-hyphens: auto;
  -moz-hyphens: auto;
}
.bubble table tr:first-child td {
  background: rgba(255, 255, 255, 0.08);
  font-weight: 600;
}
.bubble table br { display: none; } /* Remove line breaks inside tables */
.bubble table + br { display: none; } /* Remove line breaks after tables */

