function sendMessage(text) {
  busy = true;
  sendBtn.disabled = true;

  addMessage('user', text);
  const botBubble = addMessage('bot', '…thinking…', 'thinking');

  let accumulated = '';

  function finish(success = true) {
    botBubble.classList.remove('thinking');
    busy = false;
    sendBtn.disabled = false;
    msgEl.focus();

    // Display bot response (disclaimer already included in _ai_generated_note from backend)
    if (success && accumulated) {
      botBubble.innerHTML = markdownToHTML(accumulated);

      // Re-add copy button
      const copyBtn = document.createElement('button');
      copyBtn.className = 'copy-btn';
      copyBtn.textContent = 'Copy';
      copyBtn.onclick = () => copyMessage(accumulated, copyBtn);
      botBubble.appendChild(copyBtn);

      conversationHistory.push(
        { role: 'user', content: text },
        { role: 'assistant', content: accumulated }
      );

      // Keep only last 10 messages (5 exchanges) to prevent rate limits
      const MAX_HISTORY = 10;
      if (conversationHistory.length > MAX_HISTORY) {
        conversationHistory = conversationHistory.slice(-MAX_HISTORY);
      }
    }
  }

  fetch('/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      message: text,
      history: conversationHistory,
      source: 'web-chat',
      client_timestamp: new Date().toISOString()
    }),
  }).then(response => {
    const reader  = response.body.getReader();
    const decoder = new TextDecoder();
    let   buffer  = '';

    function pump() {
      return reader.read().then(({ done, value }) => {
        if (done) { finish(); return; }

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop(); // keep incomplete last line

        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const ev = JSON.parse(line);
            if (ev.type === 'text') {
              if (botBubble.classList.contains('thinking')) {
                botBubble.classList.remove('thinking');
                accumulated = '';
              }
              accumulated += ev.text;
              botBubble.innerHTML = markdownToHTML(accumulated);
              messagesEl.scrollTop = messagesEl.scrollHeight;
            } else if (ev.type === 'done') {
              finish();
            } else if (ev.type === 'error') {
              botBubble.classList.remove('thinking');
              botBubble.classList.add('error');
              botBubble.textContent = 'Error: ' + ev.error;
              finish(false);
            }
          } catch { /* malformed line, skip */ }
        }
        return pump();
      });
    }
    return pump();
  }).catch(err => {
    botBubble.classList.remove('thinking');
    botBubble.classList.add('error');
    botBubble.textContent = 'Connection error: ' + err.message;
    finish(false);
  });
}

