				<th class="sortable" onclick="sortTable(4)" data-type="number">Spectra</th>
				<th class="sortable" onclick="sortTable(5)" data-type="date">First Point</th>
				<th class="sortable" onclick="sortTable(6)" data-type="date">Last Point</th>
