	if user, ok := auth.GetUserFromContext(r.Context()); ok && user.IsAdmin {
		isSessionAdmin = true
	}

	if !isSessionAdmin {
		// Fall back to password authentication
		if *adminPassword == "" {
			http.Error(w, "Admin endpoints are disabled - please login as admin", http.StatusForbidden)
