					alert('Backfill complete: ' + data.count + ' records created');
					window.location.href = '/api/admin/uploads?password=' + password;
				} else {
					alert('Error: ' + (data.error || 'Unknown error'));
				}
			})
			.catch(err => alert('Error: ' + err));
		}

