	}() + `
		</span>`

	if userID != "" {
		params := []string{}
		if password != "" {
			params = append(params, "password="+password)
		}
		if search != "" {
			params = append(params, "search="+url.QueryEscape(search))
		}
		clearFilterURL := "/api/admin/uploads"
		if len(params) > 0 {
			clearFilterURL += "?" + strings.Join(params, "&")
		}
