	}

	// Last page
	if endPage < totalPages {
		if endPage < totalPages-1 {
			html += `<span class="page-btn disabled">...</span>`
		}
		html += `<a href="` + buildURL(totalPages) + `" class="page-btn">` + strconv.Itoa(totalPages) + `</a>`
