	log.Printf("Admin deleted track: %s", req.TrackID)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":  "success",
		"message": "Track deleted successfully",
		"trackID": req.TrackID,
	})
}

