func truncateHistory(messages []anthropicMessage, maxTokens int) []anthropicMessage {
	if len(messages) == 0 {
		return messages
	}
	total := 0
	for _, msg := range messages {
		switch c := msg.Content.(type) {
		case string:
			total += estimateTokens(c)
		case []contentBlock:
			for _, b := range c {
				total += estimateTokens(b.Text + b.Content)
