			var wg sync.WaitGroup
			batchSize := (len(uploads) + numWorkers - 1) / numWorkers

			for w := 0; w < numWorkers; w++ {
				wg.Add(1)
				start := w * batchSize
				end := start + batchSize
				if end > len(uploads) {
					end = len(uploads)
				}

				go func(start, end int) {
					defer wg.Done()
					for i := start; i < end; i++ {
						rows[i] = formatUploadRow(uploads[i], password)
					}
				}(start, end)
			}
			wg.Wait()
		}

		// Concatenate all rows
		for _, row := range rows {
			html += row
		}

		html += `
		</tbody>
	</table>`
	}

	html += `
