			})
			.catch(err => alert('Error: ' + err));
		}

		function deleteTrack(trackID) {
			if (!confirm('Delete track ' + trackID + ' and all associated data?')) {
				return;
			}

			const password = new URLSearchParams(window.location.search).get('password');

